"""Generates docs/WORKED_EXAMPLES.md and results/phase5/worked_examples.json from actual runs (no hand-typed numbers).
Evidence classes: circuit probabilities = NumPy statevector SIMULATION; Tier B = exact classical EMULATION; neither is Aer or hardware."""
import json, math, pathlib
import numpy as np
from doomsday.config import load_config
from doomsday.gridtwin.base import build_base_point
from doomsday.oracle.factory import make_oracle
from doomsday.qsearch import circuits as qc
from doomsday.qsearch.dh_gas import dh_max
from doomsday.qsearch.dicke import dicke_prep_from_reference, dicke_tree_circuit, gate_counts
from doomsday.qsearch.emulation import MarkedSet, optimal_r, p_closed, theta_of
from doomsday.qsearch.bbht import bbht_search
from doomsday.qsearch.predicate import PredicateTable
from doomsday.qsearch.statevec import ascii_diagram
from doomsday.qsearch.toy import build_toy, circuit_probabilities, emulation_probabilities

cfg = load_config(); bp = build_base_point("ieee14", cfg); md = []; js = {}
def P(s=""): md.append(s)
P("# Worked toy examples (generated by `scripts/phase5_worked_examples.py`)")
P("Evidence: gate-level results are a **NumPy statevector simulation**; Tier B is an **exact classical emulation**. Neither is Aer, hardware, or a speedup claim. Grid: IEEE-14, transcribed_from_memory_UNVERIFIED; DC predicate; candidates = branches 0..m-1 (a-priori choice, NOT a scaling shortlist).")
for m, k in ((6, 2), (8, 3)):
    o = make_oracle("dc", k, cfg, bp=bp); t = build_toy(o, range(m)); f = o.structure(); lab = lambda q: "{}-{}".format(*f.branch_keys[t.candidates[q]][:2])
    P(f"\n## Toy m={m} candidate branches, k={k}  ->  N = C({m},{k}) = {t.N}, marked M = {t.M}")
    P("Qubit q <-> branch: " + ", ".join(f"q{q}={lab(q)}" for q in range(m)) + ". Basis state bit q = 1 iff that branch is out.")
    P("| set (branches) | mask | S (DC) | marked |\n|---|---|---|---|")
    for mk, g, s in zip(t.masks, t.global_sets, t.S):
        P(f"| {', '.join(lab(q) for q in range(m) if (mk >> q) & 1)} | {mk:0{m}b} | {s:.4f} | {'**yes**' if mk in t.marked_masks else ''} |")
    grid_smax = PredicateTable.from_oracle(o).Smax; contains = t.S.max() >= grid_smax - 1e-9
    P(f"\nMarked rule: S >= S_max_in_toy - 1e-9. S_max within the toy = {t.S.max():.4f}; grid-wide S_max over all C(L,{k}) sets = {grid_smax:.4f}; the toy {'DOES' if contains else 'does NOT'} contain a grid-wide worst set (an accident of the a-priori candidate choice, never evidence about search). The marked set is computed classically and compiled into the oracle: a LOOKUP (Tier A1).")
    gc = gate_counts(m, k); P(f"\nCircuit sizes ({m} qubits): Dicke preparation from |1^k0^(m-k)> = {gc}.")
    it = qc.grover_iteration(m, k, t.marked_masks); P(f"One Grover iteration (phase oracle + reflection): {it.counts()}")
    r_max = 8; c = circuit_probabilities(t, r_max); e = emulation_probabilities(t, r_max); th = theta_of(t.N, t.M)
    P(f"\ntheta = asin(sqrt(M/N)) = {th:.5f};  r* = floor(pi/(4 theta)) = {optimal_r(t.N, t.M)}")
    P("| r | P(marked) circuit sim | Tier B emulation | sin^2((2r+1)theta) | outside-weight-k leak |\n|---|---|---|---|---|")
    for r in range(r_max + 1): P(f"| {r} | {c['p_marked'][r]:.6f} | {e['p_marked'][r]:.6f} | {float(p_closed(r, t.N, t.M)):.6f} | {c['leak_outside_weight_k'][r]:.1e} |")
    js[f"toy_{m}_{k}"] = {"N": t.N, "M": t.M, "p_circuit": c["p_marked"].tolist(), "p_tierB": e["p_marked"].tolist(), "max_abs_diff": float(np.abs(c["p_marked"] - e["p_marked"]).max())}
P("\n## Circuit descriptions (smallest instance m=4, k=2 so the diagrams stay readable; qubit 0 on top)")
P("Legend: `@` control on 1, `o` control on 0, `Ry` rotation target, `+` CNOT target, `Z` member of a multi-controlled Z, `X` bit flip.")
P("\n**Dicke state |D_2^4> from |0000> (explicit-amplitude tree of multiplexed RY; DEVIATION: not the Baertschi-Eidenbenz O(kL) circuit):**\n```\n" + ascii_diagram(dicke_tree_circuit(4, 2), 30) + "\n```")
P("**Phase oracle marking x = 0011 (X on the zero bits, MCZ on all qubits, X again):**\n```\n" + ascii_diagram(qc.phase_oracle(4, 2, [0b0011])) + "\n```")
P("**Reflection I - 2|D><D| = Tree^dagger . X^n . MCZ . X^n . Tree (first 30 ops shown):**\n```\n" + ascii_diagram(qc.reflection_about_dicke(4, 2), 30) + "\n```")
P("A full Grover circuit is: Tree (prepare |D>), then r x [phase oracle, reflection], then measurement of all m qubits.")
# accounting examples
o = make_oracle("dc", 2, cfg, bp=bp); t = build_toy(o, range(6)); pt = PredicateTable(t.S, construction_evals=t.N)
rng = np.random.default_rng(3); r = dh_max(pt, rng, record_log=True); cn = r["counter"]
P("\n## Oracle-call accounting, worked example 1: Durr-Hoyer (Tier B) on the N=15 toy table (seed 3, y0=0)")
P("Per attempt: draw j uniform in {0..ceil(m)-1}; j Grover iterations + a marking check cost **j+1 quantum oracle calls**; the measured x is verified with **1 classical evaluation**.")
P("| attempt | threshold y | m | j | measured rank x | S[x] | success (S[x] > y) | cumulative quantum calls | cumulative verifications |\n|---|---|---|---|---|---|---|---|---|")
qc_, vv = 0, 0
for i, a in enumerate(cn.log):
    qc_ += a["j"] + 1; vv += 1; P(f"| {i+1} | {a['y']:.4f} | {a['m']:.3f} | {a['j']} | {a['x']} | {pt.S[a['x']]:.4f} | {a['success']} | {qc_} | {vv} |")
P(f"\nTotals: {cn.to_dict()}.  Identities checked in tests: quantum calls = sum(j+1) = {sum(a['j']+1 for a in cn.log)}; Grover iterations = sum(j) = {sum(a['j'] for a in cn.log)}; attempts = measurements = verifications = {cn.attempts}.")
P(f"Best found: rank {r['best']} with S = {r['y']:.4f} (table maximum {pt.Smax:.4f}); terminated by `{r['terminated_by']}`. The table needed **{cn.table_construction_evals} classical evaluations to build** - NOT included in the quantum count (Tier B emulates dynamics, not realisability).")
ms = MarkedSet(56, [5, 20, 33, 41]); rb = bbht_search(ms, lambda x: x in (5, 20, 33, 41), np.random.default_rng(1), record_log=True)
P("\n## Worked example 2: BBHT threshold search, N=56, M=4 marked (unknown to the algorithm), seed 1")
P("| attempt | m | j | x | marked? | cumulative quantum calls |\n|---|---|---|---|---|---|"); qc_ = 0
for i, a in enumerate(rb["counter"].log): qc_ += a["j"] + 1; P(f"| {i+1} | {a['m']:.3f} | {a['j']} | {a['x']} | {a['success']} | {qc_} |")
P(f"\nTotals: {rb['counter'].to_dict()}; found={rb['found']}. For comparison, Grover with KNOWN M=4 would use r* = {optimal_r(56, 4)} iterations (P = {float(p_closed(optimal_r(56, 4), 56, 4)):.4f}).")
js["dh_toy_seed3"] = {"accounting": cn.to_dict(), "best": r["best"], "attempts": cn.log}; js["bbht_N56_M4_seed1"] = {"accounting": rb["counter"].to_dict(), "found": rb["found"]}
pathlib.Path("docs/WORKED_EXAMPLES.md").write_text("\n".join(md) + "\n"); pathlib.Path("results/phase5").mkdir(parents=True, exist_ok=True)
json.dump(js, open("results/phase5/worked_examples.json", "w"), indent=1, default=lambda x: x.tolist() if hasattr(x, "tolist") else str(x))
print("\n".join(md[:14])); print("..."); print("\n".join(md[-12:]))
